import "jsr:@supabase/functions-js/edge-runtime.d.ts";
const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Client-Info, Apikey",
};
const LOGO_B64 = "";
Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response(null, { status: 200, headers: corsHeaders });
  const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
  const serviceKey  = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const bytes = Uint8Array.from(atob(LOGO_B64), c => c.charCodeAt(0));
  const res = await fetch(`${supabaseUrl}/storage/v1/object/brand/logo.png`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${serviceKey}`,
      apikey: serviceKey,
      "Content-Type": "image/png",
      "x-upsert": "true",
    },
    body: bytes,
  });
  const result = await res.json().catch(() => ({}));
  const publicUrl = `${supabaseUrl}/storage/v1/object/public/brand/logo.png`;
  return new Response(JSON.stringify({ ok: res.ok, status: res.status, result, publicUrl }), {
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
});
